resposta:
Para garantir que tanto o cliente quanto o servidor utilizem o mesmo formato binário para transmitir os dados do controlador, vamos converter os arrays de inteiros usados para representar os estados dos botões e eixos em buffers binários durante a comunicação via UDP. Isso evitará problemas relacionados à interpretação incorreta dos caracteres ASCII e permitirá uma transferência mais eficiente dos dados.

Aqui estão as modificações necessárias:

### Servidor Code Modification
No servidor, precisaremos escrever diretamente os valores numéricos correspondentes aos eventos no dispositivo `uinput`. Não haverá mudanças significativas além da verificação já existente.

```cpp
static void udp_server(void) {
    int sockfd;
    struct sockaddr_in serv_addr, cli_addr;
    socklen_t cli_len = sizeof(cli_addr);
    char buffer[BUFFER_SIZE];

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("ERROR opening socket");
        exit(1);
    }

    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(PORT);

    if (bind(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {
        perror("ERROR on binding");
        exit(1);
    }

    while (1) {
        int n = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, (struct sockaddr *) &cli_addr, &cli_len);
        if (n < 0) {
            perror("ERROR in recvfrom");
        } else {
            uint16_t eventIndex;
            uint16_t eventValue;
            memcopy(&eventIndex, buffer, sizeof(uint16_t));
            memcopy(&eventValue, buffer + sizeof(uint16_t), sizeof(uint16_t));

            if ((size_t)(eventIndex) <= sizeof(REGISTERED_EVENTS)/sizeof(REGISTERED_EVENTS[0]) {
                switch (REGISTERED_EVENTS[(size_t)eventIndex].type) {
                    case EV_ABS:
                        libevdev_uinput_write_absolute(controller, REGISTERED_EVENTS[(size_t)eventIndex].code, eventValue);
