## A suitable answer to the prompt

You can use the low-level `FAudioCapture` API rather than an `AudioCaptureComponent`. Enable the **Audio Capture** plugin and add `AudioCaptureCore` to your module’s dependencies.

```cpp
// MyGameMode.h
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "AudioCapture.h"
#include "MyGameMode.generated.h"

UCLASS()
class MYGAME_API AMyGameMode : public AGameModeBase
{
    GENERATED_BODY()

public:
    virtual void BeginPlay() override;
    virtual void EndPlay(const EEndPlayReason::Type EndPlayReason) override;

private:
    FAudioCapture AudioCapture;
};
```

```cpp
// MyGameMode.cpp
#include "MyGameMode.h"

void AMyGameMode::BeginPlay()
{
    Super::BeginPlay();

    FAudioCaptureDeviceInfo DeviceInfo;
    if (!AudioCapture.GetDefaultCaptureDeviceInfo(DeviceInfo))
    {
        UE_LOG(LogTemp, Error, TEXT("No default audio capture device found."));
        return;
    }

    const int32 SampleRate = DeviceInfo.PreferredSampleRate;
    const int32 NumChannels = DeviceInfo.InputChannels;

    const auto OnCapture =
        FAudioCapture::FOnAudioCaptureFunction::CreateLambda(
            [](const void* AudioData, int32 NumFrames, int32 Channels,
               int32 Rate, double StreamTime, bool bOverflow)
            {
                // This callback runs on the audio capture thread.
                // Copy AudioData here if it must be retained; do not access
                // game-thread-only objects directly from this callback.
            });

    if (!AudioCapture.OpenDefaultCaptureStream(
            OnCapture, 1024, SampleRate, NumChannels))
    {
        UE_LOG(LogTemp, Error, TEXT("Could not open audio capture stream."));
        return;
    }

    if (!AudioCapture.StartStream())
    {
        UE_LOG(LogTemp, Error, TEXT("Could not start audio capture stream."));
        AudioCapture.CloseStream();
    }
}

void AMyGameMode::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
    if (AudioCapture.IsStreamOpen())
    {
        AudioCapture.StopStream();
        AudioCapture.CloseStream();
    }

    Super::EndPlay(EndPlayReason);
